cd /tmp && cat > t.mjs <<'EOF'
import { readFileSync } from 'node:fs';
const raw = readFileSync('/proc/self/cmdline');
const parts = [];
let cur = [];
for (const b of raw) { if (b === 0) { parts.push(cur); cur = []; } else cur.push(b); }
if (cur.length) parts.push(cur);
console.log('cmdline entries:', parts.length, 'process.argv.length:', process.argv.length);
console.log('execArgv:', JSON.stringify(process.execArgv));
const n = process.argv.length - 2;
const user = parts.slice(parts.length - n);
console.log('raw user args (hex):', user.map(a => a.map(x=>x.toString(16).padStart(2,'0')).join(' ')));
console.log('process.argv.slice(2) codepoints:', process.argv.slice(2).map(s => Array.from(s).map(c=>c.codePointAt(0).toString(16)).join(',')));
EOF
node t.mjs --c "$(printf '\xff')" --e "$(printf 'a\xc3\xa9b')"

cd /tmp && cat > u.mjs <<'EOF'
// 1. Are \p{Nd} runs always multiples of 10 in Node's Unicode data?
const nd = /\p{Nd}/u;
let runs = [], start = -1;
for (let cp = 0; cp <= 0x10FFFF; cp++) {
  if (cp >= 0xD800 && cp <= 0xDFFF) continue;
  const is = nd.test(String.fromCodePoint(cp));
  if (is && start < 0) start = cp;
  else if (!is && start >= 0) { runs.push([start, cp - start]); start = -1; }
}
if (start >= 0) runs.push([start, 0x110000 - start]);
console.log('total Nd runs:', runs.length);
console.log('runs whose length is NOT a multiple of 10:', runs.filter(r => r[1] % 10 !== 0));
console.log('runs longer than 10:', runs.filter(r => r[1] > 10).map(r => [r[0].toString(16), r[1]]));
console.log('total Nd chars:', runs.reduce((a,r)=>a+r[1],0));
// 2. category escapes support
for (const p of ['Cc','Cf','Cs','Co','Cn','Zl','Zp','Zs']) {
  try { new RegExp(`\\p{${p}}`, 'u'); console.log('OK \\p{'+p+'}'); } catch(e) { console.log('FAIL \\p{'+p+'}', e.message); }
}
console.log('node version', process.version);
EOF
node u.mjs

