/**
 * Minimal model of the Python exception objects this program can raise.
 *
 * Each exception carries what the interpreter needs to render a traceback:
 * the fully-qualified type name shown on the final line, the message body
 * (which may span several lines), the stack frames, and an optional
 * "during handling of the above exception" predecessor.
 */

export class PyException extends Error {
  /**
   * @param {string} pyType   name printed before the colon, e.g. "struct.error"
   * @param {string} pyMessage text printed after the colon, may be multi-line
   * @param {{file: string, line: number, func: string}[]} frames
   */
  constructor(pyType, pyMessage, frames = []) {
    super(`${pyType}: ${pyMessage}`);
    this.name = pyType;
    this.pyType = pyType;
    this.pyMessage = pyMessage;
    this.frames = frames;
    /** @type {PyException|null} predecessor for implicit exception chaining */
    this.during = null;
  }

  /** Prepend caller frames so the traceback reads outermost-first. */
  withOuterFrames(outer) {
    this.frames = [...outer, ...this.frames];
    return this;
  }
}

/** Raised by int() on a malformed literal; argparse catches this. */
export class PyValueError extends PyException {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyUnicodeEncodeError extends PyException {
  constructor(message) {
    super('UnicodeEncodeError', message);
  }
}

