  if (lead >= 0xc2 && lead <= 0xdf) return { length: 2, secondMin: 0x80, secondMax: 0xbf };
  if (lead === 0xe0) return { length: 3, secondMin: 0xa0, secondMax: 0xbf };
  if (lead >= 0xe1 && lead <= 0xec) return { length: 3, secondMin: 0x80, secondMax: 0xbf };
  if (lead === 0xed) return { length: 3, secondMin: 0x80, secondMax: 0x9f };
  if (lead >= 0xee && lead <= 0xef) return { length: 3, secondMin: 0x80, secondMax: 0xbf };
  if (lead === 0xf0) return { length: 4, secondMin: 0x90, secondMax: 0xbf };
  if (lead >= 0xf1 && lead <= 0xf3) return { length: 4, secondMin: 0x80, secondMax: 0xbf };
  if (lead === 0xf4) return { length: 4, secondMin: 0x80, secondMax: 0x8f };
  return null;
}

/**
 * Decode bytes as UTF-8 the way Python decodes argv: every byte that cannot
 * begin or continue a valid sequence becomes the lone surrogate U+DC00+byte,
 * so the original bytes survive round-tripping.
 */
export function fsDecode(bytes) {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const lead = bytes[i];
    const shape = sequenceShape(lead);

    if (shape === null) {
      out += String.fromCharCode(0xdc00 + lead);
      i += 1;
      continue;
    }
    if (shape.length === 1) {
      out += String.fromCharCode(lead);
      i += 1;
      continue;
    }

    const second = bytes[i + 1];
    const secondOk = second !== undefined
      && second >= shape.secondMin
      && second <= shape.secondMax;
    let valid = secondOk;
    for (let k = 2; valid && k < shape.length; k += 1) {
      valid = isContinuation(bytes[i + k]);
    }
    if (!valid) {
      out += String.fromCharCode(0xdc00 + lead);
      i += 1;
      continue;
    }

    let cp = lead & (0x7f >> shape.length);
    for (let k = 1; k < shape.length; k += 1) cp = (cp << 6) | (bytes[i + k] & 0x3f);
    out += String.fromCodePoint(cp);
    i += shape.length;
  }
  return out;
}

/**
 * `str.encode()` with the default strict handler. A surrogate left behind by
 * fsDecode cannot be encoded, and Python reports the run of offending
 * characters by position.
 */
export function encodeUtf8(text) {
  const points = [...codePoints(text)];
  const bytes = [];

  for (let index = 0; index < points.length; index += 1) {
    const cp = points[index];

    if (cp >= SURROGATE_LOW && cp <= SURROGATE_HIGH) {
      let end = index + 1;
      while (end < points.length
        && points[end] >= SURROGATE_LOW
        && points[end] <= SURROGATE_HIGH) end += 1;

      const position = end - index === 1
        ? `character ${pyStrRepr(String.fromCharCode(cp))} in position ${index}`
        : `characters in position ${index}-${end - 1}`;
      throw new PyUnicodeEncodeError(
        `'utf-8' codec can't encode ${position}: surrogates not allowed`,
      );
    }

    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return bytes;
}

