/**
 * Control-flow signals raised by ArgumentParser.
 *
 * The real argparse writes to a stream and calls sys.exit() from inside
 * parse_args(). Keeping that as data lets the entry point own all I/O.
 */

/** Raised for -h/--help: print `text` to stdout and exit 0. */
export class HelpRequested {
  constructor(text) {
    this.text = text;
  }
}

/** Raised for a usage error: print usage + message to stderr and exit 2. */
export class ParserError {
  constructor(usage, prog, message) {
    this.usage = usage;
    this.prog = prog;
    this.message = message;
  }

  render() {
    return `${this.usage}${this.prog}: error: ${this.message}\n`;
  }
}

