/**
 * argparse's HelpFormatter, reduced to the layout this parser needs:
 * a single "options:" section of store/help actions with no positionals.
 */

const INDENT = '  ';
const MAX_HELP_POSITION = 24;

/** "--a A" / "-h, --help" - the left-hand column for an action. */
export function formatInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((flag) => `${flag} ${action.metavar}`).join(', ');
}

/** How an action appears inside the usage line, bracketed when optional. */
function formatUsagePart(action) {
  const body = action.nargs === 0
    ? action.optionStrings[0]
    : `${action.optionStrings[0]} ${action.metavar}`;
  return action.required ? body : `[${body}]`;
}

/** "usage: prog [-h] --a A ...\n" */
export function formatUsage(prog, actions) {
  const parts = actions.map(formatUsagePart);
  return `usage: ${[prog, ...parts].join(' ')}\n`;
}

/**
 * The full --help text. Help strings line up in a second column whose offset
 * argparse derives from the widest invocation, capped at MAX_HELP_POSITION.
 */
export function formatHelp(prog, actions) {
  const invocations = actions.map(formatInvocation);
  const widest = invocations.reduce(
    (max, text) => Math.max(max, text.length + INDENT.length),
    0,
  );
  const helpPosition = Math.min(widest + 2, MAX_HELP_POSITION);

  let out = `${formatUsage(prog, actions)}\noptions:\n`;
  actions.forEach((action, index) => {
    const invocation = invocations[index];
    if (!action.help) {
      // Actions without help text contribute the invocation line alone, with
      // no trailing padding.
      out += `${INDENT}${invocation}\n`;
      return;
    }
    const padding = helpPosition - INDENT.length - invocation.length;
    out += `${INDENT}${invocation}${' '.repeat(Math.max(padding, 1))}${action.help}\n`;
  });
  return out;
}

