/**
 * construct's stream_write() guard, which is where fixed-size Bytes fields
 * reject data of the wrong length.
 */

import { StreamError } from './exceptions.mjs';

const NEGATIVE_LENGTH_LINE = 193;
const WRONG_LENGTH_LINE = 195;

/**
 * Validate a write of `length` bytes. The non-negative check runs first, so a
 * negative size is reported even when the data length also disagrees.
 *
 * @param {number[]} data
 * @param {bigint} length declared field size
 */
export function streamWrite(data, length) {
  if (length < 0n) {
    throw new StreamError(`length must be non-negative, found ${length}`, NEGATIVE_LENGTH_LINE);
  }
  if (BigInt(data.length) !== length) {
    throw new StreamError(
      `bytes object of wrong length, expected ${length}, found ${data.length}`,
      WRONG_LENGTH_LINE,
    );
  }
  return data;
}

