/**
 * construct's FormatField - a fixed-width integer serialised through Python's
 * struct module. Only the little-endian unsigned formats this program uses
 * are provided.
 */

import { FormatFieldError, StructError } from './exceptions.mjs';

class FormatField {
  /**
   * @param {string} fmt the struct format string, e.g. "<B"
   * @param {string} code the format character used in struct's own message
   * @param {number} byteCount width of the encoded value
   */
  constructor(fmt, code, byteCount) {
    this.fmt = fmt;
    this.code = code;
    this.byteCount = byteCount;
    this.max = (1n << BigInt(byteCount * 8)) - 1n;
  }

  /**
   * @param {bigint} value
   * @returns {number[]} little-endian bytes
   */
  build(value) {
    if (value < 0n || value > this.max) {
      // struct raises first; construct catches it and re-raises with context,
      // which is what produces the chained traceback.
      const inner = new StructError(
        `'${this.code}' format requires 0 <= number <= ${this.max}`,
      );
      const outer = new FormatFieldError(
        `struct '${this.fmt}' error during building, given value ${value}`,
      );
      outer.during = inner;
      throw outer;
    }

    const bytes = [];
    let remaining = value;
    for (let i = 0; i < this.byteCount; i += 1) {
      bytes.push(Number(remaining & 0xffn));
      remaining >>= 8n;
    }
    return bytes;
  }
}

export const Int8ul = new FormatField('<B', 'B', 1);
export const Int16ul = new FormatField('<H', 'H', 2);

