/**
 * Recovering argv exactly as CPython sees it.
 *
 * Node decodes process.argv as UTF-8 with lossy replacement, so a byte
 * sequence like 0xFF arrives as U+FFFD and becomes indistinguishable from a
 * genuine replacement character. CPython instead applies the `surrogateescape`
 * handler, preserving the original bytes as lone surrogates - which is exactly
 * why the reference build can go on to raise UnicodeEncodeError.
 *
 * On Linux the untouched bytes are still available from /proc/self/cmdline, so
 * read them there and decode them ourselves.
 */

import { readFileSync } from 'node:fs';

import { fsDecode } from '../python/codec.mjs';

const CMDLINE = '/proc/self/cmdline';

/** Split the NUL-delimited cmdline into per-argument byte arrays. */
function readRawArguments() {
  // 'latin1' maps each byte to the codepoint of the same value, giving us the
  // raw bytes without going near typed arrays.
  const raw = readFileSync(CMDLINE, 'latin1');
  const text = raw.endsWith('\0') ? raw.slice(0, -1) : raw;
  if (text === '') return [];
  return text.split('\0').map((entry) => {
    const bytes = [];
    for (let i = 0; i < entry.length; i += 1) bytes.push(entry.charCodeAt(i));
    return bytes;
  });
}

/**
 * The user-supplied arguments, decoded the way Python decodes them.
 * Falls back to Node's own view if /proc is unavailable.
 */
export function getPythonArgv() {
  const userCount = process.argv.length - 2;
  if (userCount <= 0) return [];

  try {
    const entries = readRawArguments();
    // The user's arguments are always the trailing entries: anything Node adds
    // (the interpreter path, exec flags, the script path) comes first.
    if (entries.length >= userCount) {
      return entries.slice(entries.length - userCount).map(fsDecode);
    }
  } catch {
    // Not Linux, or /proc not mounted - fall through.
  }
  return process.argv.slice(2);
}

