/**
 * Rendering an unhandled Python exception the way the frozen build reports it:
 * the interpreter's traceback, followed by PyInstaller's bootloader banner.
 */

import { PyException } from '../python/exceptions.mjs';
import { MODULE_CALL_LINE, SCRIPT_FILE, SCRIPT_NAME } from './config.mjs';

/**
 * Tag frames from the frozen script onto an exception raised beneath it, so
 * the traceback reads from module scope down into the library.
 *
 * @param {number} line source line of the failing statement inside main()
 * @param {() => T} body
 * @returns {T}
 * @template T
 */
export function atSourceLine(line, body) {
  try {
    return body();
  } catch (err) {
    if (err instanceof PyException) {
      throw err.withOuterFrames([
        { file: SCRIPT_FILE, line: MODULE_CALL_LINE, func: '<module>' },
        { file: SCRIPT_FILE, line, func: 'main' },
      ]);
    }
    throw err;
  }
}

function renderOne(exception) {
  let out = 'Traceback (most recent call last):\n';
  for (const frame of exception.frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.func}\n`;
  }
  return `${out}${exception.pyType}: ${exception.pyMessage}\n`;
}

/**
 * Full stderr text for an unhandled exception, including any implicitly
 * chained predecessor.
 */
export function renderTraceback(exception) {
  let out = '';
  if (exception.during) {
    out += renderOne(exception.during);
    out += '\nDuring handling of the above exception, another exception occurred:\n\n';
  }
  out += renderOne(exception);
  // The bootloader tags its banner with the process id.
  out += `[PYI-${process.pid}:ERROR] Failed to execute script '${SCRIPT_NAME}' due to unhandled exception!\n`;
  return out;
}

