/**
 * Buffered stdio.
 *
 * Python runs every build before printing anything, so a failure part-way
 * through produces no stdout at all. Collecting output and flushing once
 * reproduces that, and also sidesteps Node truncating pending pipe writes when
 * the process exits.
 */

const stdout = [];
const stderr = [];

/** Python's print(): the text followed by a newline. */
export function printLine(text) {
  stdout.push(`${text}\n`);
}

export function writeStdout(text) {
  stdout.push(text);
}

export function writeStderr(text) {
  stderr.push(text);
}

/** Emit everything buffered and set the process exit status. */
export function flush(exitCode) {
  if (stdout.length) process.stdout.write(stdout.join(''));
  if (stderr.length) process.stderr.write(stderr.join(''));
  stdout.length = 0;
  stderr.length = 0;
  process.exitCode = exitCode;
}

