#!/usr/bin/env node
/** Curated edge-case suite derived from black-box probing of the reference. */

import { compareAll } from './diffharness.mjs';

const base = (over = {}) => {
  const v = { a: '1', b: '1', c: 'ab', d: '2', e: 'cd', f: '1', g: '2', ...over };
  return ['--a', v.a, '--b', v.b, '--c', v.c, '--d', v.d, '--e', v.e, '--f', v.f, '--g', v.g];
};

const cases = [];

// --- sample cases -----------------------------------------------------------
cases.push(base({ a: '79', b: '54379', c: 'middle', d: '6', e: 'content', f: '50', g: '7' }));
cases.push(base({ a: '7', b: '34663', c: 'world', d: '5', e: 'string', f: '63', g: '6' }));
cases.push(base({ a: '97', b: '16011', c: 'string', d: '6', e: 'message', f: '232', g: '7' }));
cases.push(base({ a: '241', b: '3280', c: 'data', d: '4', e: 'xyz', f: '167', g: '3' }));

// --- integer field boundaries ----------------------------------------------
for (const a of ['0', '1', '127', '128', '255', '256', '-1', '-255', '999', '99999999999999999999']) {
  cases.push(base({ a }));
}
for (const b of ['0', '1', '255', '256', '65535', '65536', '-1', '4294967296']) {
  cases.push(base({ b }));
}
for (const f of ['0', '1', '128', '255', '256', '-1']) cases.push(base({ f }));

// checksum wraparound: (f+g) % 256 and (a+b) % 256
cases.push(base({ f: '255', g: '2' }));
cases.push(base({ f: '254', c: '', d: '0', e: 'xyz', g: '3' }));
cases.push(base({ a: '255', b: '65535' }));
cases.push(base({ a: '1', b: '255' }));
cases.push(base({ a: '0', b: '0', c: '', d: '0', e: '', f: '0', g: '0' }));

// --- Bytes() length handling ----------------------------------------------
cases.push(base({ c: '', d: '0' }));
cases.push(base({ c: 'abc', d: '2' }));
cases.push(base({ c: 'ab', d: '3' }));
cases.push(base({ c: 'ab', d: '-1' }));
cases.push(base({ c: '', d: '-1', e: '', g: '0' }));
cases.push(base({ d: '99999999999999999999' }));
cases.push(base({ e: 'cde', g: '2' }));
cases.push(base({ e: '', g: '0' }));
cases.push(base({ e: 'cd', g: '-5' }));

// --- bytes repr: quoting ---------------------------------------------------
for (const c of ["it's", 'he"llo', 'both\'"q', "'", '"', '\'"', '""', "''"]) {
  cases.push(base({ c, d: String(Buffer.byteLength(c, 'utf8')) }));
}

// --- bytes repr: escapes over the reachable byte range --------------------
const controls = ['\x01\x02\x03\x04\x05\x06', '\x07\x08\x0b\x0c\x1b\x7f', '\t\n\r', '\\', 'a\\b\\\\c'];
for (const c of controls) cases.push(base({ c, d: String(Buffer.byteLength(c, 'utf8')) }));
// every byte 0x01..0x7f in one payload
const lowAscii = Array.from({ length: 0x7f }, (_, i) => String.fromCharCode(i + 1)).join('');
cases.push(base({ c: lowAscii, d: String(lowAscii.length) }));
// high bytes are only reachable as valid UTF-8 sequences
for (const c of ['ÿ', '', '߿', 'ࠀ', '￿', '\u{10000}', '\u{10ffff}', 'héllo', '日本', '🎉']) {
  cases.push(base({ c, d: String(Buffer.byteLength(c, 'utf8')) }));
}
const printable = '!#$%&()*+,-./:;<=>?@[]^_`{|}~';
cases.push(base({ c: printable, d: String(printable.length) }));

// --- Python int() grammar --------------------------------------------------
const intLiterals = [
  '5', '+5', '-5', '05', '007', ' 12 ', '\t12\n', '\r12\v\f', ' 12 ',
  ' 12 ', '　12', ' 12', '12', '12', '﻿12',
  '1_2', '1_2_3', '_12', '12_', '1__2', '+1_2', '-1_2', '_', '1_',
  '0x10', '0b1', '0o7', '1e3', '1.0', '.5', 'inf', 'nan', 'None', '', ' ', '  ',
  '++5', '+-5', '- 5', '+ 5', '5-', '-', '+',
  '٥', '٥٦', '1٥', '०१', '１２', 'ᵼeᵼf',
  '\u{1d7f6}\u{1d7f7}', '²', '½', 'Ⅷ', '߁',
  '000000000000000000005',
];
for (const a of intLiterals) cases.push(base({ a }));
for (const d of ['1_0', '٥', ' 2 ', '+2']) cases.push(base({ d }));

// --- str repr in the invalid-int diagnostic ------------------------------
for (const a of ["x'y", 'x"y', 'x\'"y', 'a\\b', 'a\tb', 'a\nb', 'a\x7fb', 'héllo', '日本', '🎉', '­', '​', ' ']) {
  cases.push(base({ a }));
}

// --- argparse: forms and errors -----------------------------------------
cases.push([]);
cases.push(['--help']);
cases.push(['-h']);
cases.push(['--he']);
cases.push(['--hel']);
cases.push(['--h']);
cases.push(['--a', '1']);
cases.push(['--a', '1', '--b', '1', '--c', 'ab', '--d', '2', '--e', 'cd', '--f', '1']);
cases.push(['--a=1', '--b=1', '--c=ab', '--d=2', '--e=cd', '--f=1', '--g=2']);
cases.push(['--a=1', '--b', '1', '--c=', '--d=0', '--e=cd', '--f=1', '--g=2']);
cases.push([...base(), '--extra', '3']);
cases.push([...base(), '--extra=3']);
cases.push([...base(), 'stray']);
cases.push([...base(), '--']);
cases.push(['--', ...base()]);
cases.push([...base(), '-']);
cases.push([...base(), '-z', '-y']);
cases.push(['--extra', '1']);
cases.push(['-a', '1', '--b', '1', '--c', 'ab', '--d', '2', '--e', 'cd', '--f', '1', '--g', '2']);
cases.push(['--a']);
cases.push([...base().slice(0, -1)]);
cases.push(['--a', '--b', '1', '--c', 'ab', '--d', '2', '--e', 'cd', '--f', '1', '--g', '2']);
cases.push(['--a', 'zz', '-h']);
cases.push(['-h', '--a', 'zz']);
cases.push(['--a', 'zz']);
cases.push([...base(), '--a', '9']);
cases.push(['--a', '1', '--a', '9', '--b', '1', '--c', 'ab', '--d', '2', '--e', 'cd', '--f', '1', '--g', '2']);
// values that look like options
for (const c of ['-5', '-5.5', '-.5', '-5e3', '-x', '--b', '-', '-0', '-٥', 'a b', '-1 2']) {
  cases.push(base({ c, d: String(Buffer.byteLength(c, 'utf8')) }));
}
cases.push(['--a', '1', '--b', '1', '--c=-x', '--d', '2', '--e', 'cd', '--f', '1', '--g', '2']);
cases.push(['--a', '-5', '--b', '1', '--c', 'ab', '--d', '2', '--e', 'cd', '--f', '1', '--g', '2']);
cases.push(['--a', '1', '--b', '1', '--c', 'ab', '--d', '-3', '--e', 'cd', '--f', '1', '--g', '2']);
cases.push(['-h5']);
cases.push(['--help=x']);
cases.push(['--empty', '', ...base()]);
cases.push(base({ c: ' ', d: '1' }));

// --- error precedence: several problems at once --------------------------
cases.push(base({ a: '300', c: 'abc' }));
cases.push(base({ a: '300', b: '70000' }));
cases.push([...base({ a: '300' }), '--extra', '1']);
cases.push(['--a', 'zz', '--extra', '1']);
cases.push(base({ c: 'abc', e: 'cde' }));
cases.push(base({ a: '300', d: '-1' }));

process.exitCode = compareAll(cases, 'curated edge cases') ? 1 : 0;

