  0x2028, // LINE SEPARATOR
  0x2029, // PARAGRAPH SEPARATOR
  0x202f, // NARROW NO-BREAK SPACE
  0x205f, // MEDIUM MATHEMATICAL SPACE
  0x3000, // IDEOGRAPHIC SPACE
]);

const DECIMAL_DIGIT = /\p{Nd}/u;

// str.isprintable() is false for these categories; U+0020 is the one exception.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/** Equivalent of CPython's Py_UNICODE_ISSPACE(). */
export function isPyWhitespace(codePoint) {
  return PY_WHITESPACE.has(codePoint);
}

function isDecimalDigit(codePoint) {
  // Lone surrogates can never be Nd and String.fromCodePoint would produce an
  // unpaired unit, so short-circuit them.
  if (codePoint >= 0xd800 && codePoint <= 0xdfff) return false;
  return DECIMAL_DIGIT.test(String.fromCodePoint(codePoint));
}

// Walking back more than this from a digit means the Unicode database grew a
// run far larger than anything that has ever existed; bail out rather than spin.
const MAX_RUN_SCAN = 4096;

/**
 * Value 0-9 of a Unicode decimal digit, or -1 if the codepoint is not one.
 * Mirrors CPython's Py_UNICODE_TODECIMAL(), which is what int(str) uses.
 *
 * Unicode guarantees that decimal digits appear as blocks of exactly ten
 * consecutive codepoints ordered 0..9. Several blocks can sit back-to-back
 * (U+1D7CE..U+1D7FF is one unbroken run of fifty mathematical digits), so the
 * digit's value is its offset from the start of the maximal run, modulo ten.
 */
export function decimalDigitValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30; // ASCII fast path
  if (!isDecimalDigit(codePoint)) return -1;

  let runStart = codePoint;
  for (let steps = 0; steps < MAX_RUN_SCAN; steps += 1) {
    if (runStart === 0 || !isDecimalDigit(runStart - 1)) break;
    runStart -= 1;
  }
  return (codePoint - runStart) % 10;
}

/** Equivalent of Python's str.isprintable() for a single codepoint. */
export function isPyPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  if (codePoint >= 0xd800 && codePoint <= 0xdfff) return false; // Cs
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

/** Iterate a JS string as codepoints, yielding lone surrogates as-is. */
export function* codePoints(text) {
  for (let i = 0; i < text.length; i += 1) {
    const unit = text.charCodeAt(i);
    if (unit >= 0xd800 && unit <= 0xdbff && i + 1 < text.length) {
      const low = text.charCodeAt(i + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        yield (unit - 0xd800) * 0x400 + (low - 0xdc00) + 0x10000;
        i += 1;
        continue;
      }
    }
    yield unit;
  }
}

