/**
 * A faithful subset of Python's argparse.ArgumentParser.
 *
 * Only what test17.py exercises is modelled: long options that each take one
 * value, the implicit -h/--help, and required-argument checking. The parsing
 * order and error precedence follow CPython's _parse_known_args so that
 * diagnostics come out in the same order for the same input.
 */

import { pyStrRepr } from '../python/repr.mjs';
import { PyException } from '../python/exceptions.mjs';
import { HelpRequested, ParserError } from './exceptions.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';

// argparse's _negative_number_matcher. Python's \d is Unicode-aware, so
// non-ASCII decimal digits count here too.
const NEGATIVE_NUMBER = /^-[\p{Nd}]+$|^-[\p{Nd}]*\.[\p{Nd}]+$/u;

const PREFIX_CHARS = '-';

/** How argparse names an action in an error message. */
function actionName(action) {
  return action.optionStrings.join('/');
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      nargs: 0,
      dest: 'help',
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, options = {}) {
    const dest = options.dest ?? optionStrings[optionStrings.length - 1].replace(/^-+/, '');
    const action = {
      optionStrings,
      dest,
      nargs: options.nargs ?? 1,
      type: options.type ?? null,
      required: options.required ?? false,
      metavar: options.metavar ?? dest.toUpperCase(),
      help: options.help ?? null,
    };
    this.actions.push(action);
    for (const flag of optionStrings) this.optionStringActions.set(flag, action);
    return action;
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  error(message) {
    throw new ParserError(this.formatUsage(), this.prog, message);
  }

  /**
   * Classify one argv token. Returns null when it is a plain value, otherwise
   * a tuple describing which option it names (action === null for an option
   * the parser does not know).
   *
   * `sep` records how an inline value was attached: '=' for --opt=value, ''
   * for a value glued onto a short flag, null when there is no inline value.
   * argparse consults it to decide whether a glued value on a zero-argument
   * flag is an error or a run of further short flags.
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (!PREFIX_CHARS.includes(argString[0])) return null;

    const exact = this.optionStringActions.get(argString);
    if (exact) {
      return { action: exact, optionString: argString, explicitArg: null, sep: null };
    }

    if (argString.length === 1) return null; // a bare "-" is a value

    if (argString.includes('=')) {
      const splitAt = argString.indexOf('=');
      const optionString = argString.slice(0, splitAt);
      const known = this.optionStringActions.get(optionString);
      if (known) {
        return {
          action: known,
          optionString,
          explicitArg: argString.slice(splitAt + 1),
          sep: '=',
        };
      }
    }

    const matches = this.getOptionTuples(argString);
    if (matches.length > 1) {
      const names = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }
    if (matches.length === 1) return matches[0];

    // Nothing matched. A token that merely looks like a negative number is a
    // value, because no option string here looks like one.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null, sep: null };
  }

  /** Unambiguous-prefix matching, e.g. "--he" -> "--help". */
  getOptionTuples(argString) {
    const matches = [];

    if (PREFIX_CHARS.includes(argString[1])) {
      const splitAt = argString.indexOf('=');
      const prefix = splitAt >= 0 ? argString.slice(0, splitAt) : argString;
      const explicitArg = splitAt >= 0 ? argString.slice(splitAt + 1) : null;
      const sep = splitAt >= 0 ? '=' : null;
      for (const [flag, action] of this.optionStringActions) {
        if (flag.startsWith(prefix)) {
          matches.push({ action, optionString: flag, explicitArg, sep });
        }
      }
      return matches;
    }

    // Single-dash: either an exact short option with the rest glued on as its
    // value, or a prefix of a longer option string.
    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [flag, action] of this.optionStringActions) {
      if (flag === shortPrefix) {
        matches.push({ action, optionString: flag, explicitArg: shortExplicitArg, sep: '' });
      } else if (flag.startsWith(argString)) {
        matches.push({ action, optionString: flag, explicitArg: null, sep: null });
      }
    }
    return matches;
  }

  /** Apply an action's `type` callable, mapping ValueError to a usage error. */
  getValue(action, optionString, text) {
    if (!action.type) return text;
    try {
      return action.type.convert(text);
    } catch (err) {
      if (err instanceof PyException) {
        this.error(
          `argument ${optionString}: invalid ${action.type.name} value: ${pyStrRepr(text)}`,
        );
      }
      throw err;
    }
  }

  /** @returns {[Record<string, unknown>, string[]]} namespace and leftovers */
  parseKnownArgs(argStrings) {
    // Pass one: decide for every token whether it is an option or a value.
    // Everything after the first "--" is forced to be a value.
    const tuples = [];
    const isOption = [];
    let afterDoubleDash = false;
    for (const argString of argStrings) {
      if (afterDoubleDash) {
        tuples.push(null);
        isOption.push(false);
      } else if (argString === '--') {
        afterDoubleDash = true;
        tuples.push(null);
        isOption.push(false);
      } else {
        const tuple = this.parseOptional(argString);
        tuples.push(tuple);
        isOption.push(tuple !== null);
      }
    }

    // Pass two: consume options left to right. With no positionals declared,
    // every value token that no option claims falls through to `extras`.
    const namespace = Object.create(null);
    const extras = [];
    let i = 0;
    while (i < argStrings.length) {
      if (!isOption[i]) {
        extras.push(argStrings[i]);
        i += 1;
        continue;
      }

      const { action, optionString, explicitArg } = tuples[i];
      if (action === null) {
        extras.push(argStrings[i]);
        i += 1;
        continue;
      }

      if (action.nargs === 0) {
        if (explicitArg !== null) {
          this.error(
            `argument ${formatInvocation(action)}: ignored explicit argument ${pyStrRepr(explicitArg)}`,
          );
        }
        if (action.dest === 'help') throw new HelpRequested(this.formatHelp());
        namespace[action.dest] = true;
        i += 1;
        continue;
      }

      let raw;
      if (explicitArg !== null) {
        raw = explicitArg;
        i += 1;
      } else if (i + 1 < argStrings.length && !isOption[i + 1]) {
        raw = argStrings[i + 1];
        i += 2;
      } else {
        this.error(`argument ${optionString}: expected one argument`);
      }
      namespace[action.dest] = this.getValue(action, optionString, raw);
    }

    // Required options are reported together, in declaration order.
    const missing = this.actions
      .filter((action) => action.required && !(action.dest in namespace))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  parseArgs(argStrings) {
    const [namespace, extras] = this.parseKnownArgs(argStrings);
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

