#!/usr/bin/env node
/**
 * Randomised differential fuzz. Generates argv vectors biased toward the
 * boundaries that matter (field ranges, length agreement, exotic literals)
 * and compares the port against the reference.
 */

import { runPair } from './diffharness.mjs';

const TOTAL = Number(process.argv[2] ?? 4000);
const SEED = Number(process.argv[3] ?? 12345);

// xorshift32, so a failing run can be replayed exactly.
let state = SEED >>> 0 || 1;
function rnd() {
  state ^= state << 13; state >>>= 0;
  state ^= state >>> 17;
  state ^= state << 5; state >>>= 0;
  return state / 0x100000000;
}
const pick = (list) => list[Math.floor(rnd() * list.length)];
const intIn = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));

const INT_TOKENS = [
  '0', '1', '2', '7', '63', '127', '128', '200', '254', '255', '256', '257',
  '-1', '-2', '-256', '65534', '65535', '65536', '999999',
  '+5', ' 5 ', '\t5\n', '5_0', '0007', '٥', '１２', '０', ' 5 ',
  '', ' ', 'x', '1.0', '0x1', '--', '1_', '_1', '\x1c5', ' 5',
  '99999999999999999999999999',
];

const STR_TOKENS = [
  '', 'a', 'ab', 'abc', 'hello', 'world', 'data', 'xyz', 'message',
  "it's", 'say "hi"', 'mix\'"both', 'back\\slash', 'tab\there', 'nl\nhere',
  'cr\rhere', '\x00pad'.slice(1), '\x01\x02\x7f', 'héllo', '日本語', '🎉🎊',
  'ÿ', '', '￿', '\u{10ffff}', ' ', '-5', '-5.5', '-x', '--b',
  '=', 'a=b', '%s', '%r', "'", '"', '­', '​',
];

function utf8Len(text) {
  return Buffer.byteLength(text, 'utf8');
}

function makeCase() {
  const shape = rnd();
  const c = pick(STR_TOKENS);
  const e = pick(STR_TOKENS);

  // Most of the time keep d/g consistent with the payloads so the run reaches
  // the later build steps; otherwise deliberately desynchronise them.
  const dOk = rnd() < 0.7;
  const gOk = rnd() < 0.7;
  const d = dOk ? String(utf8Len(c)) : pick([...INT_TOKENS, String(utf8Len(c) + intIn(-2, 2))]);
  const g = gOk ? String(utf8Len(e)) : pick([...INT_TOKENS, String(utf8Len(e) + intIn(-2, 2))]);

  const a = rnd() < 0.75 ? String(intIn(0, 255)) : pick(INT_TOKENS);
  const b = rnd() < 0.75 ? String(intIn(0, 65535)) : pick(INT_TOKENS);
  const f = rnd() < 0.75 ? String(intIn(0, 255)) : pick(INT_TOKENS);

  const pairs = [['--a', a], ['--b', b], ['--c', c], ['--d', d], ['--e', e], ['--f', f], ['--g', g]];

  // Shuffle option order; argparse is order-insensitive but the port must be too.
  for (let i = pairs.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rnd() * (i + 1));
    [pairs[i], pairs[j]] = [pairs[j], pairs[i]];
  }

  const argv = [];
  for (const [flag, value] of pairs) {
    if (shape < 0.15) argv.push(`${flag}=${value}`);
    else if (shape < 0.2 && rnd() < 0.5) argv.push(`${flag}=${value}`);
    else argv.push(flag, value);
  }

  if (rnd() < 0.06) argv.splice(Math.floor(rnd() * argv.length), 1); // drop a token
  if (rnd() < 0.05) argv.push(pick(['--extra', 'stray', '--', '-', '-z', '--a']));
  if (rnd() < 0.02) argv.push(pick(['-h', '--help', '--he']));
  return argv;
}

let pass = 0;
const failures = [];
for (let i = 0; i < TOTAL; i += 1) {
  const argv = makeCase();
  const result = runPair(argv);
  if (result.ok) pass += 1;
  else if (failures.length < 12) failures.push(result);
  else failures.push({ argv, brief: true });
