/**
 * CPython's int(str) conversion.
 *
 * argparse's `type=int` calls this, so the accepted grammar has to match
 * exactly - including Unicode whitespace padding, underscore digit grouping,
 * and non-ASCII decimal digits such as U+0665 ARABIC-INDIC DIGIT FIVE.
 */

import { PyValueError } from './exceptions.mjs';
import { codePoints, decimalDigitValue, isIntLiteralWhitespace } from './unicode.mjs';
import { pyStrRepr } from './repr.mjs';

const UNDERSCORE = 0x5f;
const PLUS = 0x2b;
const MINUS = 0x2d;

/**
 * Parse a Python base-10 integer literal.
 *
 * Grammar, after stripping leading and trailing whitespace:
 *   ['+' | '-'] digit (['_'] digit)*
 * Note there is no whitespace allowed after the sign, and an underscore is
 * only legal between two digits.
 *
 * @returns {bigint} the value, with arbitrary precision like Python's int
 * @throws {PyValueError} if the text is not a valid literal
 */
export function pyInt(text) {
  const invalid = () => new PyValueError(
    `invalid literal for int() with base 10: ${pyStrRepr(text)}`,
  );

  const points = [...codePoints(text)];
  let start = 0;
  let end = points.length;
  while (start < end && isIntLiteralWhitespace(points[start])) start += 1;
  while (end > start && isIntLiteralWhitespace(points[end - 1])) end -= 1;

  let negative = false;
  if (start < end && (points[start] === PLUS || points[start] === MINUS)) {
    negative = points[start] === MINUS;
    start += 1;
  }
  if (start >= end) throw invalid();

  let value = 0n;
  let digitCount = 0;
  let previousWasUnderscore = false;

  for (let i = start; i < end; i += 1) {
    const cp = points[i];

    if (cp === UNDERSCORE) {
      // Legal only between digits: never leading, doubled, or trailing.
      if (digitCount === 0 || previousWasUnderscore) throw invalid();
      previousWasUnderscore = true;
      continue;
    }

    const digit = decimalDigitValue(cp);
    if (digit < 0) throw invalid();
    value = value * 10n + BigInt(digit);
    digitCount += 1;
    previousWasUnderscore = false;
  }

  if (digitCount === 0 || previousWasUnderscore) throw invalid();
  return negative ? -value : value;
}

/** Python's `%` on integers: the result carries the sign of the divisor. */
export function pyMod(value, modulus) {
  const remainder = value % modulus;
  if (remainder !== 0n && (remainder < 0n) !== (modulus < 0n)) {
    return remainder + modulus;
  }
  return remainder;
}

