/**
 * The slice of Python's textwrap that argparse's HelpFormatter relies on.
 */

/**
 * Greedy word wrap equivalent to textwrap.wrap() with default settings.
 * Words longer than `width` are split rather than allowed to overflow.
 *
 * @param {string} text already whitespace-normalised
 * @param {number} width maximum line length
 * @returns {string[]}
 */
export function wrap(text, width) {
  const limit = Math.max(width, 1);
  const lines = [];
  let line = '';

  for (const word of text.split(' ').filter((chunk) => chunk !== '')) {
    let remaining = word;

    if (line !== '' && line.length + 1 + remaining.length <= limit) {
      line += ` ${remaining}`;
      continue;
    }
    if (line !== '') {
      lines.push(line);
      line = '';
    }
    while (remaining.length > limit) {
      lines.push(remaining.slice(0, limit));
      remaining = remaining.slice(limit);
    }
    line = remaining;
  }

  if (line !== '') lines.push(line);
  return lines;
}

/** argparse's _whitespace_matcher pass: collapse runs of ASCII whitespace. */
export function normaliseWhitespace(text) {
  return text.replace(/[ \t\n\r\f\v]+/g, ' ').replace(/^ | $/g, '');
}

