/**
 * Terminal width discovery, matching shutil.get_terminal_size().
 */

import { pyInt } from '../python/int.mjs';

const FALLBACK_COLUMNS = 80;

/**
 * Python consults $COLUMNS first - parsed with int(), so ' 40 ', '+40' and
 * '4_0' are all accepted while '40.0' and 'abc' are not - and only asks the
 * operating system when that yields nothing usable. The query targets
 * sys.__stdout__, so a piped stdout falls back to 80 even if stderr is a tty.
 */
export function getTerminalColumns() {
  const raw = process.env.COLUMNS;
  if (raw !== undefined) {
    try {
      const parsed = pyInt(raw);
      if (parsed > 0n) return Number(parsed);
    } catch {
      // Not an integer; fall through exactly as ValueError does.
    }
  }

  const fromTty = process.stdout.columns;
  if (typeof fromTty === 'number' && fromTty > 0) return fromTty;
  return FALLBACK_COLUMNS;
}

