/**
 * argparse's HelpFormatter.
 *
 * Layout depends on the terminal width, which argparse takes from
 * shutil.get_terminal_size(). At the usual 80 columns nothing wraps, but a
 * narrow terminal reflows both the usage line and the help column, so the
 * wrapping rules are reproduced here rather than assumed away.
 */

import { normaliseWhitespace, wrap } from './textwrap.mjs';

const INDENT_INCREMENT = 2;
const MAX_HELP_POSITION = 24;
const PREFIX = 'usage: ';

// argparse splits the rendered usage string back into wrappable pieces with
// this pattern. Bracketed groups stay whole; everything else breaks on
// whitespace - which is why "--a A" can wrap between the flag and its metavar.
const USAGE_PART = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

/** "--a A" / "-h, --help" - the left-hand column for an action. */
export function formatInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((flag) => `${flag} ${action.metavar}`).join(', ');
}

/** How an action appears inside the usage line, bracketed when optional. */
function formatUsagePart(action) {
  const body = action.nargs === 0
    ? action.optionStrings[0]
    : `${action.optionStrings[0]} ${action.metavar}`;
  return action.required ? body : `[${body}]`;
}

export class HelpFormatter {
  /** @param {number} columns terminal width; argparse works two columns short */
  constructor(prog, columns) {
    this.prog = prog;
    this.width = columns - 2;
    this.maxHelpPosition = Math.min(
      MAX_HELP_POSITION,
      Math.max(this.width - 20, INDENT_INCREMENT * 2),
    );
  }

  /**
   * Fill `parts` into lines no wider than the text width.
   * When `prefix` is given the first line is measured from the prefix instead
   * of the indent, and returned without the indent so the caller can put the
   * prefix there.
   */
  getLines(parts, indent, prefix) {
    const textWidth = this.width;
    const lines = [];
    let line = [];
    let lineLen = (prefix === undefined ? indent.length : prefix.length) - 1;

    for (const part of parts) {
      if (lineLen + 1 + part.length > textWidth && line.length) {
        lines.push(indent + line.join(' '));
        line = [];
        lineLen = indent.length - 1;
      }
      line.push(part);
      lineLen += 1 + part.length;
    }
    if (line.length) lines.push(indent + line.join(' '));
    if (prefix !== undefined && lines.length) lines[0] = lines[0].slice(indent.length);
    return lines;
  }

  formatUsage(actions) {
    const { prog } = this;
    const optionalParts = actions.map(formatUsagePart);
    const flat = [prog, ...optionalParts].join(' ');

    if (PREFIX.length + flat.length <= this.width) return `${PREFIX}${flat}\n`;

    const parts = optionalParts.join(' ').match(USAGE_PART) ?? [];
    let lines;
    if (PREFIX.length + prog.length <= 0.75 * this.width) {
      // Short program name: hang the options off the end of it.
      const indent = ' '.repeat(PREFIX.length + prog.length + 1);
      lines = parts.length ? this.getLines([prog, ...parts], indent, PREFIX) : [prog];
    } else {
      // Long program name: give it a line of its own.
      const indent = ' '.repeat(PREFIX.length);
      lines = [prog, ...this.getLines(parts, indent)];
    }
    return `${PREFIX}${lines.join('\n')}\n`;
  }

  formatHelp(actions) {
    const invocations = actions.map(formatInvocation);
    const actionMaxLength = invocations.reduce(
      (max, text) => Math.max(max, text.length + INDENT_INCREMENT),
      0,
    );
    const helpPosition = Math.min(actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - INDENT_INCREMENT - 2;
    const indent = ' '.repeat(INDENT_INCREMENT);

    let out = `${this.formatUsage(actions)}\noptions:\n`;
    actions.forEach((action, index) => {
      const header = invocations[index];
      if (!action.help) {
        out += `${indent}${header}\n`;
        return;
      }

      let indentFirst;
      if (header.length <= actionWidth) {
        // Short enough to share the line with the first line of help text.
        out += `${indent}${header.padEnd(actionWidth)}  `;
        indentFirst = 0;
      } else {
        out += `${indent}${header}\n`;
        indentFirst = helpPosition;
      }

      const helpLines = wrap(normaliseWhitespace(action.help), helpWidth);
      out += `${' '.repeat(indentFirst)}${helpLines[0]}\n`;
      for (const line of helpLines.slice(1)) out += `${' '.repeat(helpPosition)}${line}\n`;
    });
    return out;
  }
}

